oxy_webhelp_navlinks = {"aws_hosted_planning-d39307e15904":{"topics":[{"title":"Licenses and usage for RSC-managed AWS protection","shortdesc":"<p class=\"shortdesc\">The license you hold determines which AWS deployment model is available when you add         an AWS cloud account, and the Licenses and Usage page shows how much capacity your hosted         accounts consume.<\/p>","href":"saas\/aws_hosted_license_usage.html","attributes":{"data-id":"aws_hosted_license_usage"},"menu":{"hasChildren":false},"tocID":"aws_hosted_license_usage-d39307e15915","topics":[]},{"title":"Supported workloads and regions for RSC-managed AWS protection","shortdesc":"<p class=\"shortdesc\">The RSC-managed model supports Amazon EC2, EBS, RDS, and S3 workloads in         commercial AWS regions, with some regions excluded.<\/p>","href":"saas\/aws_hosted_supported_workloads_regions.html","attributes":{"data-id":"aws_hosted_supported_workloads_regions"},"menu":{"hasChildren":false},"tocID":"aws_hosted_supported_workloads_regions-d39307e15926","topics":[]},{"title":"RSC-managed AWS protection limitations","shortdesc":"<p class=\"shortdesc\">Review the constraints of the RSC-managed model before you choose it for an AWS         account.<\/p>","href":"saas\/aws_hosted_limitations.html","attributes":{"data-id":"aws_hosted_limitations"},"menu":{"hasChildren":false},"tocID":"aws_hosted_limitations-d39307e15937","topics":[]},{"title":"Required permissions for RSC-managed AWS protection","shortdesc":"<p class=\"shortdesc\">RSC-managed accounts need an IAM cross-account role only, and no Exocompute,         VPC, or networking permissions in your AWS account.<\/p>","href":"saas\/aws_hosted_required_permissions.html","attributes":{"data-id":"aws_hosted_required_permissions"},"menu":{"hasChildren":false},"tocID":"aws_hosted_required_permissions-d39307e15948","topics":[]},{"title":"Vault encryption options for RSC-managed AWS protection","shortdesc":"<p class=\"shortdesc\">By default, <span class=\"ph\">RSC<\/span> manages the encryption keys for data in Rubrik Cloud         Vault, and you can specify your own key during onboarding.<\/p>","href":"saas\/aws_hosted_vault_encryption.html","attributes":{"data-id":"aws_hosted_vault_encryption"},"menu":{"hasChildren":false},"tocID":"aws_hosted_vault_encryption-d39307e15959","topics":[]}]}};